-- ============================================================================
-- 20260821_who_lms_2006_refresh.sql
-- Refreshes who_weight_for_age, who_height_for_age (Male only), and
-- who_weight_for_height with the official WHO Child Growth Standards (2006)
-- 'expanded' (daily / 0.1cm) LMS tables, generated directly from the source
-- .xlsx files downloaded from who.int/tools/child-growth-standards/standards.
--
-- Age-based rows (WFA, HFA) were interpolated from the daily table onto the
-- 0-60 month grid at day = month * 30.4375, matching how WHO derives its own
-- monthly tables from the daily ones (verified against the app's original
-- hand-entered seed to 4 decimal places before this migration was written).
--
-- who_height_for_age (Female / HAZ girls) is INTENTIONALLY NOT touched here.
-- The 'lhfa-girls-zscore-expanded-tables.xlsx' file supplied for this project
-- is not real length/height-for-age data -- it opens to a sheet literally
-- named 'BFA_girls_z_exp' with BMI-for-age values (M=13.34 at birth, not a
-- plausible newborn length). Running this against a real download of the
-- girls LHFA file from
-- https://cdn.who.int/media/docs/default-source/child-growth/child-growth-standards/indicators/length-height-for-age/expandable-tables/lhfa-girls-zscore-expanded-tables.xlsx
-- (same URL WHO publishes it at) would fix this -- upload that file next and
-- a Female HFA block can be added the same way as the Male block below.
--
-- who_weight_for_height is seeded from BOTH the birth-2y recumbent-length file
-- (45.0-110.0cm) and the 2-5y standing-height file (65.0-120.0cm), at their
-- full 0.1cm resolution -- a big precision upgrade over the old 0.5cm steps.
-- Where both files cover the same cm value (65-110cm), the standing-height
-- row is inserted last and wins, since 24-60mo (this app's scope) is measured
-- standing -- consistent with the original seed migration's documented choice.
-- ============================================================================

-- --------------------------------------------------------------------------
-- who_weight_for_age (WAZ) -- Male + Female, 0-60 months
-- --------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE L = VALUES(L), M = VALUES(M), S = VALUES(S);

-- --------------------------------------------------------------------------
-- who_height_for_age (HAZ) -- Male only, 0-60 months (see note above re: Female)
-- --------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE L = VALUES(L), M = VALUES(M), S = VALUES(S);

-- --------------------------------------------------------------------------
-- who_weight_for_height (WHZ) -- Male + Female
-- Part 1: birth-2y recumbent length (45.0-110.0cm)
-- --------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE L = VALUES(L), M = VALUES(M), S = VALUES(S);

-- --------------------------------------------------------------------------
-- who_weight_for_height (WHZ) -- Male + Female
-- Part 2: 2-5y standing height (65.0-120.0cm) -- overwrites the 65-110cm
-- overlap from Part 1 above with the standing-height curve, since that is
-- this app's 24-60mo program scope.
-- --------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE L = VALUES(L), M = VALUES(M), S = VALUES(S);
